-- Checkpoint 249 / V-07: append-only Nachhaltung von Qualitätsmaßnahmen.
-- Lokaler additiver Entwurf; bewusst nicht gegen eine produktive Datenbank ausgeführt.
CREATE TABLE IF NOT EXISTS public.qm_quality_measure_follow_ups(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
 source_deviation_id uuid NOT NULL REFERENCES public.care_quality_deviations(id) ON DELETE RESTRICT,source_deviation_sha256 text NOT NULL CHECK(source_deviation_sha256~'^[0-9a-f]{64}$'),
 deviation_category text NOT NULL CHECK(btrim(deviation_category)<>''),deviation_summary text NOT NULL CHECK(length(btrim(deviation_summary))>=5),deviation_recorded_at timestamptz NOT NULL,
 recorded_at timestamptz NOT NULL CHECK(recorded_at>=deviation_recorded_at),recorded_by uuid NOT NULL REFERENCES auth.users(id),recorded_by_name text NOT NULL CHECK(btrim(recorded_by_name)<>''),
 request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),UNIQUE(tenant_id,client_request_id),UNIQUE(tenant_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_quality_measure_follow_up_events(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,follow_up_id uuid NOT NULL REFERENCES public.qm_quality_measure_follow_ups(id) ON DELETE RESTRICT,
 sequence_no integer NOT NULL CHECK(sequence_no>=1),event_kind text NOT NULL CHECK(event_kind IN('assignment','progress','effectiveness_review','completion','reopened')),
 occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL CHECK(recorded_at>=occurred_at),actor_id uuid NOT NULL REFERENCES auth.users(id),actor_name text NOT NULL CHECK(btrim(actor_name)<>''),summary text NOT NULL CHECK(length(btrim(summary))>=5),
 action_description text,responsible_id uuid,responsible_name text,due_at timestamptz,progress_note text,observed_from timestamptz,observed_until timestamptz,
 effectiveness_outcome text CHECK(effectiveness_outcome IN('effective','partially_effective','not_effective','insufficient_evidence')),effectiveness_result text,result_sha256 text CHECK(result_sha256~'^[0-9a-f]{64}$'),
 references_event_ids uuid[] NOT NULL DEFAULT '{}',request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),
 UNIQUE(tenant_id,client_request_id),UNIQUE(follow_up_id,sequence_no),UNIQUE(follow_up_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_quality_measure_follow_up_evidence(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,follow_up_id uuid NOT NULL REFERENCES public.qm_quality_measure_follow_ups(id) ON DELETE RESTRICT,
 event_id uuid NOT NULL REFERENCES public.qm_quality_measure_follow_up_events(id) ON DELETE RESTRICT,position_no integer NOT NULL CHECK(position_no>=1),
 source_type text NOT NULL CHECK(source_type IN('deviation_original','action_record','effectiveness_record','correspondence','audit_record','other')),
 source_entity_id uuid NOT NULL,source_version_id uuid,record_locator text NOT NULL CHECK(btrim(record_locator)<>''),source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),
 UNIQUE(event_id,position_no),UNIQUE(event_id,id)
);
ALTER TABLE public.qm_quality_measure_follow_ups ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qm_quality_measure_follow_up_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qm_quality_measure_follow_up_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.qm_quality_measure_follow_ups,public.qm_quality_measure_follow_up_events,public.qm_quality_measure_follow_up_evidence FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.qm_quality_measure_follow_ups,public.qm_quality_measure_follow_up_events,public.qm_quality_measure_follow_up_evidence TO authenticated;
DROP POLICY IF EXISTS qm_quality_measure_follow_ups_read ON public.qm_quality_measure_follow_ups;
CREATE POLICY qm_quality_measure_follow_ups_read ON public.qm_quality_measure_follow_ups FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_quality_measure_follow_up_events_read ON public.qm_quality_measure_follow_up_events;
CREATE POLICY qm_quality_measure_follow_up_events_read ON public.qm_quality_measure_follow_up_events FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_quality_measure_follow_up_evidence_read ON public.qm_quality_measure_follow_up_evidence;
CREATE POLICY qm_quality_measure_follow_up_evidence_read ON public.qm_quality_measure_follow_up_evidence FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
CREATE OR REPLACE FUNCTION care_private.protect_qm_quality_measure_follow_up_history()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN RAISE EXCEPTION 'Qualitätsmaßnahmen-Nachhaltung bleibt append-only.' USING ERRCODE='42501';END$$;
DROP TRIGGER IF EXISTS protect_qm_quality_measure_follow_ups ON public.qm_quality_measure_follow_ups;
CREATE TRIGGER protect_qm_quality_measure_follow_ups BEFORE UPDATE OR DELETE ON public.qm_quality_measure_follow_ups FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_quality_measure_follow_up_history();
DROP TRIGGER IF EXISTS protect_qm_quality_measure_follow_up_events ON public.qm_quality_measure_follow_up_events;
CREATE TRIGGER protect_qm_quality_measure_follow_up_events BEFORE UPDATE OR DELETE ON public.qm_quality_measure_follow_up_events FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_quality_measure_follow_up_history();
DROP TRIGGER IF EXISTS protect_qm_quality_measure_follow_up_evidence ON public.qm_quality_measure_follow_up_evidence;
CREATE TRIGGER protect_qm_quality_measure_follow_up_evidence BEFORE UPDATE OR DELETE ON public.qm_quality_measure_follow_up_evidence FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_quality_measure_follow_up_history();

CREATE OR REPLACE FUNCTION public.record_qm_quality_measure_follow_up(p_payload jsonb,p_client_request_id uuid)RETURNS public.qm_quality_measure_follow_ups
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();actor uuid:=auth.uid();actor_name text:=public.clinical_actor_name();actual_time timestamptz:=clock_timestamp();result public.qm_quality_measure_follow_ups;prior public.qm_quality_measure_follow_ups;source_row public.care_quality_deviations;root_fp text;event_item record;evidence_item record;event_fp text;seq integer;last_kind text;last_occurred_at timestamptz;last_recorded_at timestamptz;last_reopen integer:=0;assignment_count integer;effective_count integer;refs uuid[];observed_from timestamptz;observed_until timestamptz;assignment_at timestamptz;client uuid;
BEGIN
 IF t IS NULL OR actor IS NULL OR NOT public.has_permission('qm.create_measure')THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;
 IF p_payload IS NULL OR p_client_request_id IS NULL OR p_payload->>'clientRequestId' IS DISTINCT FROM p_client_request_id::text OR COALESCE(p_payload->>'followUpId','')='' OR jsonb_typeof(p_payload->'events')<>'array' OR COALESCE(p_payload->>'sourceDeviationSha256','')!~'^[0-9a-f]{64}$' OR COALESCE(p_payload->>'deviationRecordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' OR COALESCE(p_payload->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' THEN RAISE EXCEPTION 'Maßnahmen-Nachhaltung ist unvollständig.' USING ERRCODE='23514';END IF;
 IF(p_payload->>'tenantId')::uuid IS DISTINCT FROM t THEN RAISE EXCEPTION 'Mandant ist widersprüchlich.' USING ERRCODE='23514';END IF;
 SELECT*INTO source_row FROM public.care_quality_deviations WHERE tenant_id=t AND id=(p_payload->>'sourceDeviationId')::uuid;
 IF NOT FOUND OR source_row.category IS DISTINCT FROM p_payload->>'deviationCategory' OR source_row.description IS DISTINCT FROM p_payload->>'deviationSummary' OR source_row.created_at IS DISTINCT FROM(p_payload->>'deviationRecordedAt')::timestamptz OR encode(digest(convert_to(to_jsonb(source_row)::text,'UTF8'),'sha256'),'hex')IS DISTINCT FROM p_payload->>'sourceDeviationSha256' THEN RAISE EXCEPTION 'Originalabweichung fehlt, gehört nicht zum Mandanten oder wurde nicht originalgetreu gebunden.' USING ERRCODE='23503';END IF;
 client:=source_row.client_id;root_fp:=md5(jsonb_build_object('root',p_payload-'events')::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext(p_payload->>'followUpId'));
 SELECT*INTO prior FROM public.qm_quality_measure_follow_ups WHERE tenant_id=t AND id=(p_payload->>'followUpId')::uuid;
 IF FOUND THEN IF prior.request_fingerprint IS DISTINCT FROM root_fp OR prior.client_request_id IS DISTINCT FROM p_client_request_id THEN RAISE EXCEPTION 'Nachhaltungsidentität wurde anders verwendet.' USING ERRCODE='40001';END IF;result:=prior;
 ELSE
  IF(p_payload->>'recordedBy')::uuid IS DISTINCT FROM actor OR btrim(p_payload->>'recordedByName')IS DISTINCT FROM btrim(actor_name)OR(p_payload->>'deviationRecordedAt')::timestamptz>(p_payload->>'recordedAt')::timestamptz OR(p_payload->>'recordedAt')::timestamptz>actual_time THEN RAISE EXCEPTION 'Zeitfolge oder Erfassungsidentität ist widersprüchlich.' USING ERRCODE='23514';END IF;
  INSERT INTO public.qm_quality_measure_follow_ups(id,client_request_id,tenant_id,source_deviation_id,source_deviation_sha256,deviation_category,deviation_summary,deviation_recorded_at,recorded_at,recorded_by,recorded_by_name,request_fingerprint)VALUES((p_payload->>'followUpId')::uuid,p_client_request_id,t,source_row.id,p_payload->>'sourceDeviationSha256',btrim(p_payload->>'deviationCategory'),btrim(p_payload->>'deviationSummary'),(p_payload->>'deviationRecordedAt')::timestamptz,(p_payload->>'recordedAt')::timestamptz,actor,actor_name,root_fp)RETURNING*INTO result;
 END IF;
 SELECT COALESCE(max(sequence_no),0),(array_agg(occurred_at ORDER BY sequence_no DESC))[1],(array_agg(recorded_at ORDER BY sequence_no DESC))[1],(array_agg(event_kind ORDER BY sequence_no DESC))[1]INTO seq,last_occurred_at,last_recorded_at,last_kind FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id;
 SELECT COALESCE(max(sequence_no),0)INTO last_reopen FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND event_kind='reopened';
 FOR event_item IN SELECT value,ordinality FROM jsonb_array_elements(p_payload->'events')WITH ORDINALITY LOOP
  event_fp:=md5(event_item.value::text);IF EXISTS(SELECT 1 FROM public.qm_quality_measure_follow_up_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid AND request_fingerprint=event_fp)THEN CONTINUE;END IF;
  IF EXISTS(SELECT 1 FROM public.qm_quality_measure_follow_up_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid)OR jsonb_typeof(event_item.value->'evidence')<>'array'OR jsonb_typeof(event_item.value->'referencesEventIds')<>'array'OR COALESCE(event_item.value->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR COALESCE(event_item.value->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR(event_item.value->>'occurredAt')::timestamptz>(event_item.value->>'recordedAt')::timestamptz OR(event_item.value->>'recordedAt')::timestamptz>actual_time OR(last_occurred_at IS NOT NULL AND(event_item.value->>'occurredAt')::timestamptz<last_occurred_at)OR(last_recorded_at IS NOT NULL AND(event_item.value->>'recordedAt')::timestamptz<last_recorded_at)THEN RAISE EXCEPTION 'Verlauf ist doppelt, unvollständig oder zeitlich widersprüchlich.' USING ERRCODE='40001';END IF;
  refs:=ARRAY(SELECT jsonb_array_elements_text(event_item.value->'referencesEventIds')::uuid);assignment_count:=(SELECT count(*)FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND sequence_no>last_reopen AND event_kind='assignment');effective_count:=(SELECT count(*)FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND sequence_no>last_reopen AND event_kind='effectiveness_review'AND effectiveness_outcome='effective');
  IF last_kind='completion'AND event_item.value->>'kind'<>'reopened'THEN RAISE EXCEPTION 'Erledigte Maßnahme benötigt Wiederaufnahme.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'IN('assignment','progress','effectiveness_review','completion')AND jsonb_array_length(event_item.value->'evidence')<1 THEN RAISE EXCEPTION 'Maßnahmenschritt benötigt einen konkreten Originalbeleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='assignment'AND(btrim(COALESCE(event_item.value->>'actionDescription',''))=''OR btrim(COALESCE(event_item.value->>'responsibleName',''))=''OR NULLIF(event_item.value->>'responsibleId','')IS NULL OR(event_item.value->>'dueAt')::timestamptz<=(event_item.value->>'occurredAt')::timestamptz OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='action_record'))THEN RAISE EXCEPTION 'Zuweisung benötigt Maßnahme, Verantwortung, spätere Frist und Originalbeleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='progress'AND(btrim(COALESCE(event_item.value->>'progressNote',''))=''OR NOT EXISTS(SELECT 1 FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND sequence_no>last_reopen AND event_kind='assignment'AND id=ANY(refs)))THEN RAISE EXCEPTION 'Fortschritt benötigt die aktuelle Zuweisung und einen Nachweis.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='effectiveness_review'THEN observed_from:=(event_item.value->>'observedFrom')::timestamptz;observed_until:=(event_item.value->>'observedUntil')::timestamptz;SELECT occurred_at INTO assignment_at FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND sequence_no>last_reopen AND event_kind='assignment'AND id=ANY(refs)ORDER BY sequence_no DESC LIMIT 1;IF assignment_at IS NULL OR observed_from<assignment_at OR observed_from>observed_until OR observed_until>(event_item.value->>'occurredAt')::timestamptz OR COALESCE(event_item.value->>'effectivenessOutcome','')NOT IN('effective','partially_effective','not_effective','insufficient_evidence')OR btrim(COALESCE(event_item.value->>'effectivenessResult',''))=''OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='effectiveness_record')THEN RAISE EXCEPTION 'Wirksamkeitsprüfung benötigt Zuweisung, Zeitraum, Ergebnis, Fingerprint und Originalbeleg.' USING ERRCODE='23514';END IF;END IF;
  IF event_item.value->>'kind'='completion'AND(NOT public.has_permission('qm.close_measure')OR assignment_count<1 OR effective_count<1 OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND sequence_no>last_reopen AND event_kind='assignment'AND id=ANY(refs))OR NOT EXISTS(SELECT 1 FROM public.qm_quality_measure_follow_up_events WHERE follow_up_id=result.id AND sequence_no>last_reopen AND event_kind='effectiveness_review'AND effectiveness_outcome='effective'AND id=ANY(refs)))THEN RAISE EXCEPTION 'Erledigung ohne erforderlichen wirksamen Wirksamkeitsnachweis bleibt offen.' USING ERRCODE='42501';END IF;
  IF event_item.value->>'kind'='reopened'AND(last_kind<>'completion'OR jsonb_array_length(event_item.value->'evidence')<>0)THEN RAISE EXCEPTION 'Nur eine erledigte Maßnahme kann begründet wiederaufgenommen werden.' USING ERRCODE='23514';END IF;
  seq:=seq+1;INSERT INTO public.qm_quality_measure_follow_up_events(id,client_request_id,tenant_id,follow_up_id,sequence_no,event_kind,occurred_at,recorded_at,actor_id,actor_name,summary,action_description,responsible_id,responsible_name,due_at,progress_note,observed_from,observed_until,effectiveness_outcome,effectiveness_result,result_sha256,references_event_ids,request_fingerprint)VALUES((event_item.value->>'eventId')::uuid,(event_item.value->>'clientRequestId')::uuid,t,result.id,seq,event_item.value->>'kind',(event_item.value->>'occurredAt')::timestamptz,(event_item.value->>'recordedAt')::timestamptz,actor,actor_name,btrim(event_item.value->>'summary'),NULLIF(btrim(COALESCE(event_item.value->>'actionDescription','')),''),NULLIF(event_item.value->>'responsibleId','')::uuid,NULLIF(btrim(COALESCE(event_item.value->>'responsibleName','')),''),NULLIF(event_item.value->>'dueAt','')::timestamptz,NULLIF(btrim(COALESCE(event_item.value->>'progressNote','')),''),NULLIF(event_item.value->>'observedFrom','')::timestamptz,NULLIF(event_item.value->>'observedUntil','')::timestamptz,NULLIF(event_item.value->>'effectivenessOutcome',''),NULLIF(btrim(COALESCE(event_item.value->>'effectivenessResult','')),''),NULLIF(event_item.value->>'resultSha256',''),refs,event_fp);
  FOR evidence_item IN SELECT value,ordinality FROM jsonb_array_elements(event_item.value->'evidence')WITH ORDINALITY LOOP IF COALESCE(evidence_item.value->>'sourceType','')NOT IN('deviation_original','action_record','effectiveness_record','correspondence','audit_record','other')OR btrim(COALESCE(evidence_item.value->>'recordLocator',''))=''OR COALESCE(evidence_item.value->>'sourceSha256','')!~'^[0-9a-f]{64}$'THEN RAISE EXCEPTION 'Beleg ist unvollständig.' USING ERRCODE='23514';END IF;INSERT INTO public.qm_quality_measure_follow_up_evidence(id,tenant_id,follow_up_id,event_id,position_no,source_type,source_entity_id,source_version_id,record_locator,source_sha256)VALUES((evidence_item.value->>'evidenceId')::uuid,t,result.id,(event_item.value->>'eventId')::uuid,evidence_item.ordinality,evidence_item.value->>'sourceType',(evidence_item.value->>'sourceEntityId')::uuid,NULLIF(evidence_item.value->>'sourceVersionId','')::uuid,btrim(evidence_item.value->>'recordLocator'),evidence_item.value->>'sourceSha256');END LOOP;
  last_kind:=event_item.value->>'kind';last_occurred_at:=(event_item.value->>'occurredAt')::timestamptz;last_recorded_at:=(event_item.value->>'recordedAt')::timestamptz;IF last_kind='reopened'THEN last_reopen:=seq;END IF;
 END LOOP;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)VALUES(t,client,'qm_quality_measure_follow_up',result.id,'quality_measure_follow_up_recorded','Qualitätsmaßnahme append-only fortgeschrieben; Abweichung, Verantwortung, Frist, tatsächliche Wirksamkeit und Erledigung bleiben getrennt.',to_jsonb(result),actor,actor_name);RETURN result;
END$$;
REVOKE ALL ON FUNCTION public.record_qm_quality_measure_follow_up(jsonb,uuid)FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_qm_quality_measure_follow_up(jsonb,uuid)TO authenticated;
